&lt;/div&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; style=&quot;text-align: justify;&quot; data-offset-key=&quot;6os4h-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;6os4h-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6os4h-0-0&quot;&gt;&lt;span data-offset-key=&quot;6os4h-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Publish deep-dive videos that connect search, vector databases, and agentic workflows. Or covers observability with logs, metrics, and traces including the OpenTelemetry perspective.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;bn2ig-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;bn2ig-0-0&quot;&gt;&lt;span data-offset-key=&quot;bn2ig-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Stay up to date with the latest trends in search and AI or observability to cover what&#39;s new and exciting for our users.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;2n5on-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;2n5on-0-0&quot;&gt;&lt;span data-offset-key=&quot;2n5on-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Build open-source demos and example applications on GitHub that combine Elasticsearch with developer and AI tools.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;d0ho2-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;d0ho2-0-0&quot;&gt;&lt;span data-offset-key=&quot;d0ho2-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Contribute to Elasticsearch Labs and our YouTube channel.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;p&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;31scv-0-0&quot;&gt;
