&lt;/div&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; style=&quot;text-align: justify;&quot; data-offset-key=&quot;6os4h-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;82h45&quot; data-offset-key=&quot;6os4h-0-0&quot;&gt;
